CREATE TABLE schools (id BIGSERIAL PRIMARY KEY, name VARCHAR(180) NOT NULL, code VARCHAR(40) NOT NULL UNIQUE, email VARCHAR(180), phone VARCHAR(40), address TEXT, active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE app_users (id BIGSERIAL PRIMARY KEY, full_name VARCHAR(180) NOT NULL, email VARCHAR(180) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE school_memberships (id BIGSERIAL PRIMARY KEY, school_id BIGINT NOT NULL REFERENCES schools(id), user_id BIGINT NOT NULL REFERENCES app_users(id), role VARCHAR(40) NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, UNIQUE(school_id,user_id));
CREATE TABLE classrooms (id BIGSERIAL PRIMARY KEY, school_id BIGINT NOT NULL REFERENCES schools(id), name VARCHAR(100) NOT NULL, academic_year VARCHAR(30), UNIQUE(school_id,name));
CREATE TABLE students (id BIGSERIAL PRIMARY KEY, school_id BIGINT NOT NULL REFERENCES schools(id), classroom_id BIGINT REFERENCES classrooms(id), admission_number VARCHAR(80) NOT NULL, first_name VARCHAR(100) NOT NULL, last_name VARCHAR(100) NOT NULL, date_of_birth DATE, active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(school_id,admission_number));
CREATE TABLE guardians (id BIGSERIAL PRIMARY KEY, school_id BIGINT NOT NULL REFERENCES schools(id), full_name VARCHAR(180) NOT NULL, phone VARCHAR(40) NOT NULL, email VARCHAR(180), active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE student_guardians (id BIGSERIAL PRIMARY KEY, student_id BIGINT NOT NULL REFERENCES students(id), guardian_id BIGINT NOT NULL REFERENCES guardians(id), relationship VARCHAR(60), receives_notifications BOOLEAN NOT NULL DEFAULT TRUE, UNIQUE(student_id,guardian_id));
CREATE TABLE qr_credentials (id BIGSERIAL PRIMARY KEY, school_id BIGINT NOT NULL REFERENCES schools(id), student_id BIGINT NOT NULL REFERENCES students(id), token_hash VARCHAR(64) NOT NULL UNIQUE, active BOOLEAN NOT NULL DEFAULT TRUE, issued_at TIMESTAMPTZ NOT NULL DEFAULT now(), revoked_at TIMESTAMPTZ);
CREATE TABLE attendance_events (id BIGSERIAL PRIMARY KEY, school_id BIGINT NOT NULL REFERENCES schools(id), student_id BIGINT NOT NULL REFERENCES students(id), event_type VARCHAR(20) NOT NULL, event_time TIMESTAMPTZ NOT NULL DEFAULT now(), actor_user_id BIGINT NOT NULL REFERENCES app_users(id), idempotency_key VARCHAR(100), UNIQUE(school_id,idempotency_key));
CREATE INDEX idx_attendance_school_time ON attendance_events(school_id,event_time);
CREATE TABLE notifications (id BIGSERIAL PRIMARY KEY, school_id BIGINT NOT NULL REFERENCES schools(id), student_id BIGINT NOT NULL REFERENCES students(id), attendance_event_id BIGINT NOT NULL REFERENCES attendance_events(id), recipient_phone VARCHAR(40) NOT NULL, message TEXT NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'PENDING', provider_reference VARCHAR(180), attempts INTEGER NOT NULL DEFAULT 0, last_error TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), sent_at TIMESTAMPTZ, UNIQUE(attendance_event_id,recipient_phone));
CREATE TABLE audit_events (id BIGSERIAL PRIMARY KEY, school_id BIGINT REFERENCES schools(id), actor_user_id BIGINT REFERENCES app_users(id), action VARCHAR(100) NOT NULL, entity_type VARCHAR(100), entity_id VARCHAR(80), details TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
